<?php
require __DIR__.'/security.php';
runtime_save(['NIKXOR_PUBLIC_URL'=>'https://verify.example.test/app']);
security_establish_session($ou);
$pdo->prepare('INSERT INTO sales (invoice_no,customer_name,customer_phone,total_amount,paid_amount,remaining_amount,profit,payment_type,currency_code,shop_id,created_at) VALUES (?,?,?,100,0,100,0,?,?,?,?)')->execute(['VERIFY-'.bin2hex(random_bytes(6)),'PRIVATE-CUSTOMER','PRIVATE-PHONE','قرض','AFN',$a1,date('Y-m-d H:i:s')]);$id=(int)$pdo->lastInsertId();$q=$pdo->prepare('SELECT * FROM sales WHERE id=?');$q->execute([$id]);$sale=$q->fetch();
$token=invoice_verification_token($sale);check(invoice_verification_find($token)['id']==$id,'signed verification token resolves real stored invoice');check(invoice_verification_token($sale)===$token,'reprinting keeps same verification token');
$url=invoice_verification_url($sale);check(str_starts_with($url,'https://verify.example.test/app/verify_invoice.php?t='),'QR uses configured HTTPS origin and actual verification route');
$changed=substr($token,0,-1).(substr($token,-1)==='A'?'B':'A');check(invoice_verification_find($changed)===null,'modified QR signature cannot verify invoice');check(invoice_verification_find('999999.'.$token)===null,'invented invoice identifier rejected');check(invoice_verification_find([])===null,'malformed verification input rejected');
$details=invoice_verification_details(invoice_verification_find($token));check($details['total']==='100.00'&&$details['remaining']==='100.00','verification preserves unpaid invoice amount and balance');check(!str_contains(json_encode($details),'PRIVATE-'),'public verification details omit customer identity and phone');check(array_diff(array_keys($details),['business_name','invoice_no','issued_at','currency','total','remaining','returned','return_documents','fully_returned'])===[],'public payload contains only approved fields');
$pdo->prepare("INSERT INTO sales_returns (shop_id,sale_id,reason,status,created_by,request_key,total_amount,currency_code,content_hash) VALUES (?,?,'Test','partial',?,?,25,'AFN',?)")->execute([$a1,$id,$owner,bin2hex(random_bytes(16)),hash('sha256','verification-fixture')]);$details=invoice_verification_details(invoice_verification_find($token));check($details['returned']==='25.00'&&$details['return_documents']===1&&!$details['fully_returned'],'verification reflects partial returns from database');
$caught=false;try{invoice_verification_token(['id'=>99999999,'shop_id'=>$a1]);}catch(InvalidArgumentException $e){$caught=true;}check($caught,'no QR token can be issued for nonexistent sale');
$pdo->prepare('UPDATE sales SET verification_nonce=? WHERE id=?')->execute([bin2hex(random_bytes(16)),$id]);check(invoice_verification_find($token)===null,'changed nonce invalidates old QR token');
check(invoice_public_origin('http://unsafe.example')===null,'verification QR rejects plaintext origin');check(invoice_public_origin('https://name:secret@example.test')===null,'verification QR rejects credential-bearing origin');check(invoice_public_origin('https://example.test/a/../b')===null,'verification QR rejects parent-path origin');check(invoice_public_origin('https://example.test/app?fake=1')===null,'verification QR rejects query-bearing origin');
putenv('NIKXOR_PUBLIC_URL=http://unsafe.example');check(invoice_verification_url($sale)===null,'no fake QR printed when HTTPS origin is missing');putenv('NIKXOR_PUBLIC_URL');
$oldDocumentRoot=$_SERVER['DOCUMENT_ROOT'];$privateRuntime=runtime_directory();$_SERVER['DOCUMENT_ROOT']=$privateRuntime;$caught=false;try{runtime_directory();}catch(RuntimeException $e){$caught=true;}finally{$_SERVER['DOCUMENT_ROOT']=$oldDocumentRoot;}check($caught,'misconfigured document root cannot expose runtime keys');
echo "Invoice verification scenarios completed.\n";
